public void dispatchCargo(Long cargoId, String destinationPath) throws IOException {
    warehouseRepository.decrementStock(cargoId);
    // Выброс проверяемого IOException: Spring по умолчанию закоммитит транзакцию!
    if (!fileStorage.exists(destinationPath)) {
        throw new IOException("Manifest file path unreachable: " + destinationPath);
    }
    manifestService.createEntry(cargoId, destinationPath);
}

public OrderResult checkout(Long orderId, BigDecimal amount) {
    validateOrder(orderId);
    paymentClient.charge(amount);
    // ВНИМАНИЕ: Вызов метода того же класса через this!
    this.saveAuditRecord(orderId, "CHARGED");
    return new OrderResult("SUCCESS");
}

public void saveAuditRecord(Long orderId, String action) {
    auditRepository.save(new AuditLog(orderId, action));
}

public List<ProductDto> browseCatalog(String categoryId, int page) {
    return productRepository.findByCategory(categoryId, PageRequest.of(page, 50))
        .stream()
        .map(ProductDto::fromEntity)
        .toList();
}

public UserSession authenticate(String username, String password) {
    User user = userRepository.findByUsername(username);
    if (!passwordEncoder.matches(password, user.getPasswordHash())) {
        // Запись в аудит должна зафиксироваться независимо от отката текущей транзакции!
        securityAuditService.logFailedAttempt(username);
        throw new BadCredentialsException("Invalid credentials");
    }
    return sessionManager.createSession(user);
}

public void logFailedAttempt(String username) {
    auditRepository.save(new SecurityEvent(username, "FAILED_LOGIN", Instant.now()));
}

@TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)
public void onOrderCreated(OrderCreatedEvent event) {
    kafkaTemplate.send("orders-topic", event.orderId(), event.payload());
    // ОШИБКА: Физическая транзакция уже закоммичена! Вызов без REQUIRES_NEW молча потеряет изменения!
    orderRepository.markNotificationDispatched(event.orderId());
}

public void issueBonus(Long accountId, BigDecimal points) {
    validateAccount(accountId);
    // Вызов private метода с @Transactional: Spring AOP полностью проигнорирует аннотацию!
    computeAndPersistBonus(accountId, points);
}

// ВНИМАНИЕ: private метод! Аннотация не имеет эффекта!
private void computeAndPersistBonus(Long accountId, BigDecimal points) {
    bonusLedgerRepository.record(accountId, points);
}

public boolean processSubscription(Long subId, String cardToken) {
    subscriptionRepo.markAttempt(subId);
    try {
        // ОШИБКА: chargeCard выполняется в REQUIRED. Выброс исключения пометит всю транзакцию как RollbackOnly!
        paymentGatewayService.chargeCard(subId, cardToken);
        return true;
    } catch (CardDeclinedException ex) {
        // Перехват исключения бесполезен: транзакция уже испорчена!
        bonusService.deductPointsFallback(subId);
        return false;
    }
}

public void chargeCard(Long subId, String cardToken) {
    bankClient.charge(cardToken);
}

public RouteResult processTransfer(Long routeId, Coordinates destination) {
    // ВНИМАНИЕ: Сетевой I/O внутри @Transactional удерживает JDBC-соединение все 3000 мс!
    RouteCoordinates coords = mappingClient.calculateOptimalRoute(destination);
    return routePersistenceService.saveRoutePlan(routeId, coords);
}

public RouteResult saveRoutePlan(Long routeId, RouteCoordinates coords) {
    routeRepository.updatePlan(routeId, coords);
    return new RouteResult(routeId, "PLANNED");
}

public ReconciliationReport reconcileInventory(Long warehouseId) {
    long initialCount = inventoryRepo.countAvailable(warehouseId);
    performAuditSanityCheck(warehouseId);
    // В READ_COMMITTED параллельный коммит изменит результат второго чтения!
    long verifiedCount = inventoryRepo.countAvailable(warehouseId);
    return new ReconciliationReport(warehouseId, initialCount, verifiedCount);
}

@Retryable(retryFor = OptimisticLockException.class, maxAttempts = 3)
public void transferFunds(Long fromId, Long toId, BigDecimal sum) {
    Account from = accountRepo.findByIdWithOptimisticLock(fromId);
    Account to = accountRepo.findByIdWithOptimisticLock(toId);
    from.debit(sum);
    to.credit(sum);
}

public BookingResult bookTrip(Long tripId, FlightInfo flight, HotelInfo hotel) {
    flightBookingService.bookFlight(tripId, flight);
    try {
        hotelBookingService.bookHotel(tripId, hotel);
    } catch (HotelUnavailableException ex) {
        // Запуск компенсирующей транзакции!
        flightBookingService.compensateFlight(tripId);
        return BookingResult.failed("Hotel unavailable, flight cancelled");
    }
    return BookingResult.confirmed(tripId);
}

public void bookFlight(Long tripId, FlightInfo flight) {
    flightRepo.reserve(tripId, flight);
}

public void compensateFlight(Long tripId) {
    flightRepo.cancel(tripId);
}

public AuditSnapshot auditReconciliation(LocalDate auditDate) {
    // ОПАСНОСТЬ: Использование READ_UNCOMMITTED может оставить сокет в грязном состоянии!
    return auditRepository.extractDailyLedger(auditDate);
}

public void processInvoice(Invoice invoice) {
    invoiceRepository.save(invoice);
    // Вызов внешнего сервиса с REQUIRES_NEW: запрашивает второе соединение!
    auditLogService.recordEvent(invoice.getId(), "INVOICE_PROCESSED");
}

public void recordEvent(Long entityId, String eventType) {
    auditRepository.save(new AuditLog(entityId, eventType));
}

@Async
public CompletableFuture<Report> generateFiscalReport(Long companyId, int fiscalYear) {
    // В новом потоке ThreadLocal пуст! Транзакция родителя не наследуется!
    Company company = companyRepo.findByIdWithLedgers(companyId);
    Report rep = calculateLedger(company, fiscalYear);
    return CompletableFuture.completedFuture(rep);
}

public boolean cancelShift(Long doctorId, LocalDate shiftDate) {
    long activeDoctors = shiftRepo.countActiveDoctors(shiftDate);
    if (activeDoctors >= 2) {
        shiftRepo.markDoctorOffDuty(doctorId, shiftDate);
        return true;
    }
    return false;
}

public PaymentReceipt payOrder(Long orderId, BigDecimal amount) {
    orderRepo.markPaid(orderId, amount);
    try {
        // Попытка списания баллов через точку сохранения NESTED
        loyaltyPointService.deductPoints(orderId, amount.intValue());
    } catch (InsufficientPointsException ex) {
        // Ошибка списания баллов откатит только savepoint, не затрагивая оплату заказа!
        orderRepo.logNote(orderId, "Paid fully with cash");
    }
    return new PaymentReceipt(orderId, "CONFIRMED");
}

public void deductPoints(Long orderId, int points) {
    loyaltyRepo.subtract(orderId, points);
}
